    </div>
    <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:40px">
      <div style="text-align:center"><div style="height:4px;background:#2ECC71;border-radius:2px;margin-bottom:6px"></div><div style="font-size:10px;color:#888">FORMAT</div><div style="font-size:12px">15/15</div></div>
      <div style="text-align:center"><div style="height:4px;background:#2ECC71;border-radius:2px;margin-bottom:6px"></div><div style="font-size:10px;color:#888">EDUCATION</div><div style="font-size:12px">15/15</div></div>
      <div style="text-align:center"><div style="height:4px;background:#2ECC71;border-radius:2px;margin-bottom:6px"></div><div style="font-size:10px;color:#888">EXPERIENCE</div><div style="font-size:12px">30/30</div></div>
      <div style="text-align:center"><div style="height:4px;background:#F39C12;border-radius:2px;margin-bottom:6px"></div><div style="font-size:10px;color:#888">BULLETS</div><div style="font-size:12px">20/25</div></div>
      <div style="text-align:center"><div style="height:4px;background:#2ECC71;border-radius:2px;margin-bottom:6px"></div><div style="font-size:10px;color:#888">POSITIONING</div><div style="font-size:12px">15/15</div></div>
    </div>
  </div>
</div>

<div class="ctrl-panel">
  <div class="ctrl-header">
    <h3>DESIGN CONTROLS</h3>
    <button onclick="toggleCtrlPanel()">−</button>
  </div>
  <div class="ctrl-body">
    <div class="ctrl-group">
      <label>HEADING FONT</label>
      <select id="ctrl-heading-font" onchange="updateRootVar('--heading-font',this.value)">
        <option value="'Georgia', serif">Georgia</option>
        <option value="'Arial', sans-serif">Arial</option>
        <option value="'Courier', monospace">Courier</option>
        <option value="'Times', serif">Times</option>
      </select>
    </div>
    <button class="btn-reset" onclick="resetTheme()">Reset</button>
  </div>
</div>

<script>
document.querySelectorAll('.tab-btn').forEach(function(btn){
  btn.addEventListener('click',function(){
    document.querySelectorAll('.tab-btn').forEach(function(b){b.classList.remove('active')});
    document.querySelectorAll('.tab-content').forEach(function(c){c.classList.remove('active')});
    btn.classList.add('active');
    document.getElementById(btn.getAttribute('data-tab')).classList.add('active');
  });
});
function selectCard(card){
  var section=card.closest('.dc-section');
  if(section){section.querySelectorAll('.dc-card').forEach(function(c){c.classList.remove('selected')})}
  card.classList.add('selected');
  var v=card.getAttribute('data-var');
  var val=card.getAttribute('data-val');
  if(v&&val&&v!=='visual-only'){updateRootVar('--'+v,val)}
}
function updateRootVar(n,v){document.documentElement.style.setProperty(n,v)}
function resetTheme(){document.documentElement.removeAttribute('style')}
function toggleCtrlPanel(){document.querySelector('.ctrl-panel').classList.toggle('collapsed')}
</script></body></html>`);
